use ingetrazo_core::sheet_shape::ShapePath;use glam::DVec2;use ingetrazo_render::qt_gray::Segment;
fn main(){let mut path=ingetrazo_gui::composer_cad::source_closed_curve(&ShapePath::RoundedRect{size:DVec2::new(40.,25.),radius:8.}).unwrap();let p=|p:[f64;2]|[p[0]*2.+12.25,p[1]*2.+12.5];path.start=p(path.start);for s in &mut path.segments{match s{Segment::Line(to)=>*to=p(*to),Segment::Cubic{control1,control2,to}=>{*control1=p(*control1);*control2=p(*control2);*to=p(*to);}}}let spans=ingetrazo_render::qt_cosmetic::rasterize_path(&path,true,0.7,100000).unwrap();let rows=spans.iter().filter(|s|s.y==12&&s.x<=28&&i64::from(s.x)+i64::from(s.len)>28).map(|s|[s.x as i64,s.y as i64,s.len as i64,s.coverage as i64]).collect::<Vec<_>>();println!("{}",serde_json::to_string(&rows).unwrap());}
